import sympy as s
from calibration_bank import LEVELS,L
M=s.Matrix
k,h,t,u=s.symbols('k h t u',real=True)
PATHS={'inconsistent-geometry':'MAT.geometry-system.inconsistent','nonunique-geometry':'MAT.geometry-system.nonunique','cross-linearity':'VEC.vector-properties.linearity'}
RATIONALES={
'inconsistent-geometry':['Recognise disjoint parallel planes.','Distinguish pairwise intersection from common intersection.','Identify inconsistent planes by elimination.','Determine all pairwise intersection lines and their relationship.','Recover parameter for a common intersection.','Classify inconsistent systems and their pairwise geometry over two parameters.'],
'nonunique-geometry':['Identify a free coordinate geometrically.','Distinguish a common line from a common plane.','Find a common line by elimination.','Find a common plane and verify all equations.','Reconstruct a plane containing a prescribed common line.','Classify common intersection dimensions and give full solution sets.'],
'cross-linearity':['Scale a vector.','Diagnose false distributivity involving a scalar.','Expand a cross product using bilinearity.','Recover scalar coefficients from independent cross products.','Reconstruct vectors from a cross-product constraint.','Classify all vector pairs with prescribed cross product and fixed sum; enrichment proof.']}

def make(path,l,v):
 if path not in PATHS or l not in LEVELS or v not in (1,2,3):raise ValueError('Unknown cell')
 a=v+1;b=v+3;d=2*v+5
 if path=='inconsistent-geometry':
  if l==1:
   f=[False];q=f'Do the planes x={a} and x={b} have any common point? Explain geometrically.';ans='No.';steps=['Their normals are the same nonzero vector.',f'Their x-coordinates must be both {a} and {b}, which is impossible; the planes are distinct and parallel.'];hint=['Compare normals.','Compare constants.'];mist='Assuming equal normals imply coincident planes.'
  elif l==2:
   f=[False,M([a,b,t])];q=f'A student claims that x={a}, y={b}, x+y={a+b+1} share a point because each pair intersects. Refute the claim, giving the common line of the first two planes.';ans=f'No common point; first two meet in {L(f[1])}, t real.';steps=[f'The first two fix x={a}, y={b}, leaving z=t.',f'The third demands x+y={a+b+1}, but the forced sum is {a+b}.', 'Each pair has independent normals and intersects in a line, but the three lines have no common point.'];hint=['Use the first two equations together.','Check the third equation.'];mist='Confusing pairwise intersection with simultaneous intersection.'
  elif l==3:
   f=[False,d];q=f'Use elimination to decide whether the planes x+{a}y={b}, y+z={d}, x+{a+1}y+z={b+2*d} have a common point. Explain the geometric conclusion.';ans=f'No common point; contradiction 0={d}.';steps=['Subtract the first and second equations from the third.',f'The left side is zero but the right side is {d}.','The contradiction means the common intersection is empty.'];hint=['Look for a sum of two left sides.','Compare the right sides.'];mist='Assuming three planes must meet at a point.'
  elif l==4:
   f=[M([a,b,t]),M([a,b+d,t]),M([a+d,b,t])];q=f'Find the three pairwise intersection lines of x={a}, y={b}, x+y={a+b+d}. Show geometrically why no point belongs to all three.';ans='Lines: '+', '.join(L(e) for e in f)+', t real.';steps=[f'The first two give {L(f[0])}.',f'The first and third give {L(f[1])}.',f'The second and third give {L(f[2])}.','All have direction (0,0,1) but distinct fixed coordinate pairs, so no two of these lines meet.'];hint=['Solve pairs separately.','Compare the directions and fixed coordinates.'];mist='Reporting only one pairwise intersection.'
  elif l==5:
   f=[b+2*d,M([b-a*(d-t),d-t,t])];q=f'Planes x+{a}y={b}, y+z={d} and x+{a+2}y+2z=k have a common point only for certain k. Determine all such k and describe the common intersection. For every other k, prove that all three pairwise intersections exist but no common point exists.';ans=f'k={f[0]}; common line {L(f[1])}, t real; otherwise no common point but every pair intersects.';steps=[f'The first two planes force x+{a+2}y+2z={b}+2({d})={b+2*d}.',f'The third agrees exactly when k={b+2*d}.',f'At this value choose z=t, y={d}-t, x={b}-{a}({d}-t), giving {L(f[1])}.','Otherwise the required constants contradict each other; all pairs still have independent normals, so each pair meets in a line.'];hint=['Compare the third normal with a combination of the first two.','Check constants and independence of each pair of normals.'];mist='Assuming pairwise intersections guarantee consistency.' 
  else:
   f=[a,b,M([a,b,t]),M([a,b+h-b,t]),M([a+(h-b)/(k-a),b,t])];q=f'For all real k,h classify the common intersection of x={a}, y={b}, (k-{a})(x-{a})+(y-{b})=h-{b}. In every inconsistent case describe the pairwise intersections, distinguishing parallel disjoint pairs from three distinct parallel intersection lines. Give all line equations and justify completeness.';ans=f'h={b}: common line {L(f[2])}. h not equal to {b}, k={a}: second and third disjoint; other pairs give {L(f[2])}, {L(f[3])}. h not equal to {b}, k not equal to {a}: three distinct parallel lines {L(f[2])}, {L(f[3])}, {L(f[4])}. In all line equations t is real.';steps=[f'The first two force x={a}, y={b}; substituting gives 0=h-{b}.',f'When h={b}, their entire line {L(f[2])} satisfies the third equation.',f'When h differs from {b}, the common intersection is empty. If k={a}, the third becomes y=h, parallel and distinct from the second; the other two pairs give {L(f[2])}, {L(f[3])}.',f'If k differs from {a}, the third normal has both x and y components nonzero, so all pairs meet. The first and third give {L(f[3])}, the second and third give {L(f[4])}, and the first two give {L(f[2])}. Their fixed coordinate pairs are distinct and all directions are (0,0,1). These cases exhaust the parameters.'];hint=['Substitute the forced coordinates first.','In the inconsistent case check whether the third normal is proportional to either of the others.'];mist='Concluding every inconsistent system contains a parallel pair of planes.'
 elif path=='nonunique-geometry':
  if l==1:
   f=[M([a,b,t])];q=f'Describe the entire common intersection of x={a} and y={b}, using a vector equation.';ans=L(f[0])+', t real.';steps=['The first two coordinates are fixed.',f'The third is arbitrary, so the intersection is the line {L(f[0])}.'];hint=['Which coordinate is unrestricted?','Use a free parameter for it.'];mist='Giving just one point on the line.'
  elif l==2:
   f=[M([a,t,u])];q=f'A student says x={a}, 2x={2*a}, {b}x={a*b} intersect in a line because there are three equations. Explain and give the actual common set.';ans=L(f[0])+', t,u real; a plane.';steps=['Each equation simplifies to the same equation.',f'The two remaining coordinates are independent and unrestricted: {L(f[0])}.','The common set is a plane, not a line.'];hint=['Divide each equation by its nonzero coefficient.','Count free coordinates, not equations.'];mist='Assuming three equations guarantee at least two independent constraints.'
  elif l==3:
   f=[M([d-t-a*(b-t),b-t,t])];q=f'Find a vector equation of the common intersection of x+{a}y+z={d}, y+z={b}, x+{a+1}y+2z={d+b}. Verify all three.';ans=L(f[0])+', t real.';steps=['The third equation is the sum of the first two.',f'Choose z=t, so y={b}-t.',f'The first then gives x={d}-t-{a}({b}-t), yielding {L(f[0])}.','Substitution verifies all equations; the two independent constraints force these coordinates.'];hint=['Identify a redundant equation.','Choose one coordinate freely.'];mist='Giving two independent free parameters despite two independent equations.'
  elif l==4:
   f=[M([d-a*t-b*u,t,u])];q=f'Find the complete common intersection of x+{a}y+{b}z={d}, -2x-{2*a}y-{2*b}z={-2*d}, 3x+{3*a}y+{3*b}z={3*d}. Give its vector equation with two independent directions and verify.';ans=L(f[0])+', t,u real.';steps=['The second and third equations are nonzero multiples of the first, including their constants.',f'Choose y=t and z=u, giving {L(f[0])}.',f'The direction vectors (-{a},1,0) and (-{b},0,1) are independent.','Substitution recovers every constant; every common point arises from its own y,z coordinates.'];hint=['Compare full equations including constants.','Choose two free coordinates.'];mist='Comparing only coefficient multiples and neglecting the constants.'
  elif l==5:
   K=s.Rational(b-d,b+2*d);H=2*K+1;V=M([a+t,b+2*t,d-t]);f=[K,H,V];q=f'Find real k,h such that the plane x+ky+hz={a+b} contains the entire intersection of y-2x={b-2*a} and z+x={d+a}. Give the common line and prove uniqueness.';ans=f'k={L(K)}, h={L(H)}; common line {L(V)}, t real.';steps=[f'Parameterise the intersection as {L(V)}, t real.',f'Substitution into the proposed plane gives constant term {a}+{b}k+{d}h and coefficient 1+2k-h of t.',f'For every t the coefficient must vanish and the constant must equal {a+b}. Hence h=1+2k and {b}k+{d}h={b}.',f'Solving gives k={L(K)}, h={L(H)}; the coefficient {b+2*d} is nonzero. Substitution verifies every point, and the first two equations already restrict the common set to the line.'];hint=['Use a free parameter for the common line.','An identity in the free parameter forces two separate equations.'];mist='Checking only one point of the line rather than every point.' 
  else:
   f=[a,b,d,M([a,b,t]),M([a,t,u])];q=f'For every real k,h consider x={a}, x+(k-{a})(y-{b})={a}, x+(k-{a})(y-{b})={a}+h-{d}. Classify the common intersection as empty, a line or a plane; give the full vector equations and prove no unique point is possible.';ans=f'h not equal to {d}: empty. h={d}, k not equal to {a}: {L(f[3])}, t real. h={d}, k={a}: {L(f[4])}, t,u real.';steps=[f'The second and third have identical left sides, so consistency requires h={d}.',f'At h={d}, subtract x={a} from the second: (k-{a})(y-{b})=0.',f'If k differs from {a}, y={b}, giving {L(f[3])}. If k={a}, every equation is x={a}, giving {L(f[4])}.','The free z-coordinate in every consistent case precludes a unique point. All cases follow from reversible equations.'];hint=['Compare the second and third constants.','Separate zero and nonzero coefficients before dividing.'];mist='Dividing by k minus its exceptional value and losing the common-plane case.'
 else:
  A=M([1,a,0]);B=M([0,1,b]);C=M([d,0,1]);D=A.cross(B);E=A.cross(C)
  if l==1:
   f=[a*B];q=f'Calculate {a} times the vector {L(B)}.';ans=L(f[0]);steps=['Multiply each component by the scalar.',f'The result is {L(f[0])}.'];hint=['Do not add the scalar.','Scale every component.'];mist='Scaling only the first component.'
  elif l==2:
   f=[a*D,a*a*D];q=f'A student claims ({a}A) cross ({a}B) equals {a}(A cross B), with A={L(A)}, B={L(B)}. Find both sides and explain the error.';ans=f'Claimed {L(f[0])}; actual {L(f[1])}.';steps=[f'A cross B={L(D)}.',f'Each scalar factor can be taken outside independently; the actual factor is {a*a}, not {a}.',f'The claimed vector {L(f[0])} differs from {L(f[1])}.'];hint=['Extract one scalar at a time.','Compare the total factor.'];mist='Extracting only one of two scalar factors.'
  elif l==3:
   f=[a*D-b*E];q=f'Let A={L(A)}, B={L(B)}, C={L(C)}. Use distributivity to expand A cross ({a}B-{b}C) and calculate the result.';ans=L(f[0]);steps=[f'A cross B={L(D)} and A cross C={L(E)}.',f'Bilinearity gives {a}(A cross B)-{b}(A cross C)={L(f[0])}.'];hint=['Keep A as the first factor.','Distribute and extract scalars.'];mist='Reversing the order of one cross product.'
  elif l==4:
   W=b*D-d*E;f=[b,-d];q=f'Let A={L(A)}, B={L(B)}, C={L(C)}. Find p,q such that A cross (pB+qC)={L(W)}. Prove uniqueness.';ans=f'p={b}, q={-d}.';steps=[f'Expand as p{L(D)}+q{L(E)}.',f'The two product vectors are independent: their cross product is {L(D.cross(E))}, nonzero.',f'Comparing entries yields p={b}, q={-d}; substitution verifies the result. Independence proves uniqueness.'];hint=['Expand before solving.','Check independence of the two resulting vectors.'];mist='Cancelling the vector A as if it were a scalar.'
  elif l==5:
   V=b*B+d*C;W=A.cross(V);f=[V+t*A];q=f'Given A={L(A)}, find every vector X satisfying A cross X={L(W)}. You may use the particular vector {L(V)}; justify the complete family.';ans=L(f[0])+', t real.';steps=[f'The supplied particular vector gives A cross V={L(W)}.', 'Subtract using distributivity: A cross (X-V)=0.',f'Because A is nonzero, X-V must be a scalar multiple of A (including zero). Thus X={L(f[0])}.','Every member satisfies the original equation because A cross A=0.'];hint=['Subtract a known solution.','Use the condition for a zero cross product.'];mist='Assuming cross-product cancellation gives just one solution.'
  else:
   S=M([a,0,0]);X=M([t,-h/a,k/a]);Y=S-X;f=[X,Y,s.Rational(a,2),False];q=f'For every real k,h find all vector pairs X,Y satisfying X+Y={L(S)} and X cross Y=(0,k,h). Then impose |X|=|Y| and determine whether the pair is unique. Finally, explain why replacing (0,k,h) with (1,k,h) makes the system impossible. Prove completeness.';ans=f'X={L(X)}, Y={L(Y)}, t real. Equal magnitudes force t={s.Rational(a,2)}; unique ordered pair. Nonzero first component impossible.';steps=['Substitute Y=S-X and use distributivity and X cross X=0, so X cross Y=X cross S.',f'Writing X=(t,y,z) gives X cross S=(0,{a}z,-{a}y). Matching (0,k,h) gives z=k/{a}, y=-h/{a}.',f'Thus X={L(M([t,-h/a,k/a]))}, Y={L(S-M([t,-h/a,k/a]))}.',f'The perpendicular components of X and Y are opposites, so equal squared lengths require t^2=({a}-t)^2, giving t={s.Rational(a,2)} uniquely.','The first component of X cross S is always zero, so a first component of one is impossible. The parameterisation and reversible constraints prove completeness.'];X=M([t,-h/a,k/a]);Y=S-X;f=[X,Y,s.Rational(a,2),False];ans=f'X={L(X)}, Y={L(Y)}, t real. Equal magnitudes force t={s.Rational(a,2)}; unique ordered pair. Nonzero first component impossible.';hint=['Substitute Y=S-X before expanding.','Compare squared magnitudes after finding the general pair.'];mist='Treating a cross product as commutative or cancelling a vector.'
 def enc(e):
  if type(e) is bool:return e
  if isinstance(e,s.MatrixBase):return {'matrix':[[str(x) for x in row] for row in e.tolist()]}
  return str(e)
 return dict(path=path,focus_skill=PATHS[path],tier=l,variant=v,assessment_role='prerequisite_bridge' if l==1 else 'concept_diagnostic' if l==2 else 'direct_focus_task',question_latex=q,final_answer_latex=ans,worked_solution_latex=steps,progressive_hints=hint,rubric=[dict(marks=1,criterion=e) for e in steps],facts=[enc(e) for e in f],likely_mistake=mist,origin='original',examination_source=None,difficulty_status='editorial_design_teacher_pending',demand_rationale=RATIONALES[path][l-1])
